HISTORY = [dict(zip(('date', 'title', 'author', 'source_type', 'text'), line.split('|'))) for line in HISTORY.splitlines()]
for index, item in enumerate(HISTORY):
    item['id'] = f"jane-history-{index + 1:02d}"
    kind = item['source_type'].lower()
    if 'vaccination' in kind:
        event_type = 'vaccination'
    elif 'nursing communication' in kind or item['author'] in ('Jane Doe', 'Emily Doe, daughter') and not any(x in kind for x in ('preferences', 'preparation')):
        event_type = 'observation'
    elif any(x in kind for x in ('care-plan', 'mobility plan', 'preferences', 'preparation')):
        event_type = 'care-plan'
    elif any(x in kind for x in ('prescription', 'medication chart', 'pharmacist')):
        event_type = 'medication'
    elif 'results' in kind and 'imaging' not in kind:
        event_type = 'results-review'
    elif any(x in kind for x in ('pathology', 'ecg', 'imaging', 'investigation', 'monitoring completion', 'fbe')):
        event_type = 'investigation'
    elif 'care-staff monitoring' in kind:
        event_type = 'monitoring'
    elif 'discharge summary' in kind:
        event_type = 'discharge'
    elif 'ed attendance' in kind:
        event_type = 'hospital'
    else:
        event_type = 'appointment'
    item['event_type'] = event_type
